'use client';

import React, { useEffect, useRef, useState } from 'react';
import { animate, stagger, remove } from 'animejs';
import {
  Train,
  ChevronLeft,
  ChevronRight,
  Info,
  Layers,
  Utensils,
  Zap,
  Luggage,
  Users,
  CheckCircle2,
} from 'lucide-react';

export interface FormattedCoach {
  code: string;
  name: string;
  category: string;
  type: string;
  color: string;
  position: number;
}

interface CoachVisualizerProps {
  coaches: FormattedCoach[];
  rakeType?: string | null;
  totalCoaches?: number;
  trainNo?: string;
  trainName?: string;
}

const COACH_COLOR_MAP: Record<string, { bg: string; text: string; border: string; glow: string }> = {
  rose: {
    bg: 'bg-rose-500/15 dark:bg-rose-500/20',
    text: 'text-rose-600 dark:text-rose-400',
    border: 'border-rose-500/35',
    glow: 'shadow-rose-500/20',
  },
  indigo: {
    bg: 'bg-indigo-500/15 dark:bg-indigo-500/20',
    text: 'text-indigo-600 dark:text-indigo-400',
    border: 'border-indigo-500/35',
    glow: 'shadow-indigo-500/20',
  },
  blue: {
    bg: 'bg-blue-500/15 dark:bg-blue-500/20',
    text: 'text-blue-600 dark:text-blue-400',
    border: 'border-blue-500/35',
    glow: 'shadow-blue-500/20',
  },
  teal: {
    bg: 'bg-teal-500/15 dark:bg-teal-500/20',
    text: 'text-teal-600 dark:text-teal-400',
    border: 'border-teal-500/35',
    glow: 'shadow-teal-500/20',
  },
  cyan: {
    bg: 'bg-cyan-500/15 dark:bg-cyan-500/20',
    text: 'text-cyan-600 dark:text-cyan-400',
    border: 'border-cyan-500/35',
    glow: 'shadow-cyan-500/20',
  },
  sky: {
    bg: 'bg-sky-500/15 dark:bg-sky-500/20',
    text: 'text-sky-600 dark:text-sky-400',
    border: 'border-sky-500/35',
    glow: 'shadow-sky-500/20',
  },
  violet: {
    bg: 'bg-violet-500/15 dark:bg-violet-500/20',
    text: 'text-violet-600 dark:text-violet-400',
    border: 'border-violet-500/35',
    glow: 'shadow-violet-500/20',
  },
  emerald: {
    bg: 'bg-emerald-500/15 dark:bg-emerald-500/20',
    text: 'text-emerald-600 dark:text-emerald-400',
    border: 'border-emerald-500/35',
    glow: 'shadow-emerald-500/20',
  },
  amber: {
    bg: 'bg-amber-500/15 dark:bg-amber-500/20',
    text: 'text-amber-600 dark:text-amber-400',
    border: 'border-amber-500/35',
    glow: 'shadow-amber-500/20',
  },
  orange: {
    bg: 'bg-orange-500/15 dark:bg-orange-500/20',
    text: 'text-orange-600 dark:text-orange-400',
    border: 'border-orange-500/35',
    glow: 'shadow-orange-500/20',
  },
  purple: {
    bg: 'bg-purple-500/15 dark:bg-purple-500/20',
    text: 'text-purple-600 dark:text-purple-400',
    border: 'border-purple-500/35',
    glow: 'shadow-purple-500/20',
  },
  zinc: {
    bg: 'bg-zinc-800 text-amber-400',
    text: 'text-amber-400',
    border: 'border-zinc-700',
    glow: 'shadow-amber-500/20',
  },
  slate: {
    bg: 'bg-slate-500/15 dark:bg-slate-500/20',
    text: 'text-slate-600 dark:text-slate-400',
    border: 'border-slate-500/35',
    glow: 'shadow-slate-500/15',
  },
};

const BERTH_LAYOUT_GUIDE: Record<string, string> = {
  '1A': 'AC First Class • Lockable 2-berth coupes and 4-berth cabins with private attendant call button',
  HA: 'Composite Coach • Divided section between AC First Class (1A) and AC 2-Tier (2A)',
  '2A': 'AC 2-Tier • 48–54 Berths • 2 Upper + 2 Lower in bays, plus 2 Side berths across the aisle',
  '3A': 'AC 3-Tier • 64–72 Berths • 6 Berths per compartment (Lower, Middle, Upper) + 2 Side berths',
  '3E': '3-Tier Economy • 72–83 Berths • Modern high-capacity LHB modular 3-tier air-conditioned coach',
  CC: 'AC Chair Car • 73–78 Seats • 3x2 cushioned reclining seating layout with overhead racks',
  EC: 'Executive Chair Car • 46–56 Seats • 2x2 spacious premium leather reclining chairs with footrests',
  SL: 'Sleeper Class • 72–80 Berths • Non-air-conditioned open window sleeping bays',
  '2S': 'Second Sitting • 108 Seats • 3x3 reserved cushioned bench seats for daytime intercity routes',
  GS: 'General Unreserved • First-come first-serve unreserved passenger travel coach',
  PC: 'Pantry / Hot Buffet Car • Railway catering kitchen preparing hot meals, tea, and beverages en route',
  EOG: 'End-On Generation Car • Diesel generator supplying electricity for air-conditioning and lights',
  SLR: 'Seating cum Luggage Rake • Guard compartment, passenger seats, and parcel luggage space',
  ENG: 'Locomotive WAP-7 / WAP-5 / WDP-4D • Dual-cab electric or diesel engine powering the train rake',
};

export const CoachVisualizer: React.FC<CoachVisualizerProps> = ({
  coaches,
  rakeType,
  totalCoaches,
  trainNo,
}) => {
  const containerRef = useRef<HTMLDivElement>(null);
  const scrollRef = useRef<HTMLDivElement>(null);
  const [selectedIndex, setSelectedIndex] = useState<number>(0);

  // Staggered arrival animation powered by Anime.js v4
  useEffect(() => {
    if (!containerRef.current || !coaches || coaches.length === 0) return;

    try {
      const items = containerRef.current.querySelectorAll('.coach-pill-item');
      if (items.length > 0) {
        animate(items, {
          translateX: [30, 0],
          opacity: [0, 1],
          scale: [0.9, 1],
          delay: stagger(30, { start: 50 }),
          duration: 400,
          ease: 'outQuad',
        });
      }
    } catch {
      // Graceful fallback for non-animation environments
    }

    return () => {
      try {
        const items = containerRef.current?.querySelectorAll('.coach-pill-item');
        if (items && items.length > 0) {
          remove(items);
        }
      } catch {}
    };
  }, [coaches]);

  if (!coaches || coaches.length === 0) {
    return null;
  }

  const selectedCoach = coaches[selectedIndex] || coaches[0];
  const total = totalCoaches || coaches.length;

  const handleScroll = (direction: 'left' | 'right') => {
    if (scrollRef.current) {
      const offset = direction === 'left' ? -260 : 260;
      scrollRef.current.scrollBy({ left: offset, behavior: 'smooth' });
    }
  };

  return (
    <div
      ref={containerRef}
      className="p-3.5 sm:p-4 rounded-2xl bg-card border border-strong shadow-sm space-y-3"
    >
      {/* ── Top Controls & Rake Info ── */}
      <div className="flex items-center justify-between gap-2 flex-wrap">
        <div className="flex items-center gap-2">
          <div className="inline-flex items-center gap-1.5 px-2.5 py-1 rounded-lg bg-primary/10 border border-primary/20 text-primary font-bold text-xs">
            <Layers className="w-3.5 h-3.5" />
            <span>
              {total} Coaches {rakeType ? `• ${rakeType}` : ''}
            </span>
          </div>
          <span className="text-[11px] text-muted font-medium hidden sm:inline">
            Engine to Rear Sequence
          </span>
        </div>

        {/* Scroll Buttons */}
        <div className="flex items-center gap-1">
          <button
            type="button"
            onClick={() => handleScroll('left')}
            aria-label="Scroll coaches left"
            className="p-1.5 rounded-lg border border-subtle bg-input/40 hover:bg-input text-secondary hover:text-main transition-colors cursor-pointer"
          >
            <ChevronLeft size={14} />
          </button>
          <button
            type="button"
            onClick={() => handleScroll('right')}
            aria-label="Scroll coaches right"
            className="p-1.5 rounded-lg border border-subtle bg-input/40 hover:bg-input text-secondary hover:text-main transition-colors cursor-pointer"
          >
            <ChevronRight size={14} />
          </button>
        </div>
      </div>

      {/* ── Horizontal Train Track & Coaches ── */}
      <div className="relative">
        <div
          ref={scrollRef}
          className="overflow-x-auto custom-scrollbar pb-2.5 pt-1 px-1 flex items-center gap-1.5 scroll-smooth"
        >
          {/* Locomotive Engine graphic at front */}
          <div className="coach-pill-item shrink-0 flex items-center">
            <button
              type="button"
              onClick={() => setSelectedIndex(0)}
              className={`flex flex-col items-center justify-center w-14 h-14 rounded-xl border transition-all text-center cursor-pointer ${
                selectedIndex === 0
                  ? 'bg-zinc-900 border-amber-500 shadow-md ring-2 ring-amber-500/40 text-amber-400'
                  : 'bg-zinc-900/90 border-zinc-700 hover:border-zinc-500 text-zinc-300'
              }`}
              title="Locomotive Engine (Front)"
            >
              <Train size={18} className="text-amber-400" />
              <span className="text-[10px] font-black uppercase tracking-wider mt-0.5">
                LOCO
              </span>
            </button>
            <div className="w-1.5 h-0.5 bg-subtle shrink-0" />
          </div>

          {/* Passenger & Utility Coaches */}
          {coaches.map((coach, idx) => {
            // If the first item in coach data was already an engine, skip duplicate visual engine
            if (idx === 0 && (coach.category === 'ENG' || coach.code === 'L')) {
              return null;
            }

            const colorStyle = COACH_COLOR_MAP[coach.color] || COACH_COLOR_MAP.slate;
            const isSelected = selectedIndex === idx;

            return (
              <React.Fragment key={`${coach.code}-${idx}`}>
                <button
                  type="button"
                  onClick={() => setSelectedIndex(idx)}
                  className={`coach-pill-item shrink-0 flex flex-col items-center justify-between w-13 h-14 p-1.5 rounded-xl border transition-all cursor-pointer select-none ${
                    colorStyle.bg
                  } ${colorStyle.border} ${
                    isSelected
                      ? `ring-2 ring-primary scale-105 shadow-md ${colorStyle.glow}`
                      : 'hover:brightness-110 active:scale-95'
                  }`}
                  title={`${coach.code} (${coach.name})`}
                >
                  <span className="text-[9px] font-bold text-muted uppercase tracking-tight">
                    #{idx + 1}
                  </span>
                  <span
                    className={`font-black font-mono text-xs tracking-tight ${colorStyle.text}`}
                  >
                    {coach.code}
                  </span>
                  <span className="text-[8px] font-semibold text-secondary truncate max-w-[42px]">
                    {coach.category}
                  </span>
                </button>
                {idx < coaches.length - 1 && (
                  <div className="w-1.5 h-0.5 bg-subtle shrink-0" />
                )}
              </React.Fragment>
            );
          })}
        </div>
      </div>

      {/* ── Selected Coach Inspector Card ── */}
      {selectedCoach && (
        <div className="p-3 rounded-xl bg-input/30 border border-subtle flex flex-col sm:flex-row items-start sm:items-center justify-between gap-3 text-xs animate-in fade-in duration-150">
          <div className="flex items-start sm:items-center gap-2.5 min-w-0">
            <div
              className={`p-2 rounded-lg shrink-0 ${
                COACH_COLOR_MAP[selectedCoach.color]?.bg || 'bg-primary/10'
              } ${
                COACH_COLOR_MAP[selectedCoach.color]?.border || 'border border-primary/20'
              }`}
            >
              {selectedCoach.category === 'PC' ? (
                <Utensils className="w-4 h-4 text-purple-500" />
              ) : selectedCoach.category === 'EOG' ? (
                <Zap className="w-4 h-4 text-slate-400" />
              ) : selectedCoach.category === 'SLR' ? (
                <Luggage className="w-4 h-4 text-slate-400" />
              ) : selectedCoach.category === 'GS' ? (
                <Users className="w-4 h-4 text-amber-500" />
              ) : (
                <CheckCircle2 className="w-4 h-4 text-primary" />
              )}
            </div>

            <div className="min-w-0">
              <div className="flex items-center gap-2 flex-wrap">
                <span className="font-black text-main text-sm font-mono">
                  {selectedCoach.code}
                </span>
                <span className="text-secondary font-bold truncate">
                  {selectedCoach.name}
                </span>
                <span className="text-[10px] font-mono px-2 py-0.5 rounded bg-card border border-subtle text-muted">
                  Position: #{selectedCoach.position} of {total}
                </span>
              </div>
              <p className="text-[11px] text-muted mt-0.5 line-clamp-2">
                {BERTH_LAYOUT_GUIDE[selectedCoach.category] ||
                  `Standard Indian Railways coach configuration for class ${selectedCoach.code}.`}
              </p>
            </div>
          </div>

          <div className="shrink-0 flex items-center gap-1.5 text-[10px] text-muted self-end sm:self-center">
            <Info size={12} className="text-primary shrink-0" />
            <span>Tap any coach to inspect</span>
          </div>
        </div>
      )}

      {/* ── Quick Color Legend ── */}
      <div className="pt-1 border-t border-subtle flex items-center gap-3 text-[10px] text-muted overflow-x-auto custom-scrollbar select-none whitespace-nowrap">
        <span className="font-bold text-secondary">Classes:</span>
        <span className="inline-flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-rose-500" /> 1A
        </span>
        <span className="inline-flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-blue-500" /> 2A
        </span>
        <span className="inline-flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-teal-500" /> 3A
        </span>
        <span className="inline-flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-cyan-500" /> 3E
        </span>
        <span className="inline-flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-sky-500" /> CC
        </span>
        <span className="inline-flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-emerald-500" /> SL
        </span>
        <span className="inline-flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-amber-500" /> GS
        </span>
        <span className="inline-flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-purple-500" /> Pantry
        </span>
        <span className="inline-flex items-center gap-1">
          <span className="w-2 h-2 rounded-full bg-slate-500" /> Power/SLR
        </span>
      </div>
    </div>
  );
};
